// Generated by Suite Builder from a crawl of the site. The Jira loop: ready stories in, outcomes back out.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Your Jira names go in jira/jira.properties.
// The Jira loop (G-208), run by the suite's pipeline, or by hand:
//   node jira/sync.mjs check    signs in, says what is ready and which statuses it can reach; changes nothing
//   node jira/sync.mjs pull     the stories in the ready status, into stories/new/ (answers into stories/done/)
//   node jira/sync.mjs report   each story's outcome as a comment, and its card moved on or back to triage
// Settings: jira/jira.properties. Secrets, from the environment only, never a file: JIRA_API_TOKEN, and
// for Jira Cloud JIRA_EMAIL (the account the token belongs to).
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SETTINGS = join(ROOT, 'jira', 'jira.properties');
const REPORTED = join(ROOT, 'jira', 'reported.json');
const NEW = join(ROOT, 'stories', 'new');
const DONE = join(ROOT, 'stories', 'done');
/** The first line of every comment this script writes: how it tells its own comments from a person's. */
const MARK = "Suite Builder: the suite's AI crew";

class Stop extends Error {}
class Idle extends Stop {}

/** The team's settings, checked: every name the loop needs, and its edition. */
function settings() {
  if (!existsSync(SETTINGS)) throw new Stop('jira/jira.properties is missing: a rebuild of the suite writes it again.');
  const s = { edition: 'cloud', max: '5' };
  for (const line of readFileSync(SETTINGS, 'utf8').split(/\r?\n/)) {
    const m = /^\s*([a-z]+)\s*=\s*(.*?)\s*$/.exec(line);
    if (m && !line.trimStart().startsWith('#')) s[m[1]] = m[2];
  }
  // Not set up at all: pull and report have nothing to do, and say so; check says what to fill in.
  if (!s.site && !s.project && process.argv[2] !== 'check') throw new Idle('Jira is not set up (jira/jira.properties): nothing to do.');
  const missing = ['site', 'project', 'ready', 'implemented', 'triage'].filter((k) => !s[k]);
  if (missing.length) throw new Stop(`Jira is not set up yet: fill in ${missing.join(', ')} in jira/jira.properties.`);
  if (s.edition !== 'cloud' && s.edition !== 'data-center') throw new Stop(`edition in jira/jira.properties is "${s.edition}": write cloud or data-center.`);
  s.max = Math.max(1, Number.parseInt(s.max, 10) || 5);
  s.site = s.site.replace(/\/+$/, '');
  return s;
}

/** The sign-in Jira asks for: an email and an API token on Cloud, a personal access token on Data Center. */
function signIn(s) {
  const token = process.env.JIRA_API_TOKEN;
  if (!token) throw new Stop('JIRA_API_TOKEN is not set: add it to the pipeline\'s secrets (never to a file in the suite).');
  if (s.edition === 'data-center') return `Bearer ${token}`;
  const email = process.env.JIRA_EMAIL;
  if (!email) throw new Stop('JIRA_EMAIL is not set: on Jira Cloud the token goes with the email of the account it belongs to.');
  return `Basic ${Buffer.from(`${email}:${token}`).toString('base64')}`;
}

const WHY = {
  401: 'Jira refused the sign-in: check JIRA_API_TOKEN (and JIRA_EMAIL on Cloud), and that edition in jira/jira.properties is right.',
  403: 'the account signed in may not do this: give it permission to browse, comment on and move the project\'s issues.',
  404: 'Jira has no such thing: check site and project in jira/jira.properties.',
};

/** One call to Jira's version 2 REST API, which both editions answer alike. */
async function call(s, auth, method, path, body) {
  let res;
  try {
    res = await fetch(`${s.site}${path}`, {
      method,
      headers: { Authorization: auth, Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}) },
      body: body ? JSON.stringify(body) : undefined,
    });
  } catch (e) {
    throw new Stop(`Jira at ${s.site} did not answer (${e.cause?.code ?? e.message}): check site in jira/jira.properties, and that the pipeline can reach it.`);
  }
  if (!res.ok) throw new Stop(`Jira answered ${res.status} to ${method} ${path.split('?')[0]}: ${WHY[res.status] ?? (await res.text()).slice(0, 200)}`);
  return res.status === 204 ? null : res.json();
}

/** The stories waiting in the ready status, oldest first. Cloud searches at /search/jql, Data Center at /search. */
async function ready(s, auth, max) {
  const jql = `project = "${s.project}" AND status = "${s.ready}" ORDER BY created ASC`;
  const where = s.edition === 'cloud' ? '/rest/api/2/search/jql' : '/rest/api/2/search';
  const found = await call(s, auth, 'GET', `${where}?jql=${encodeURIComponent(jql)}&fields=summary,description&maxResults=${max}`);
  return found.issues ?? [];
}

async function comments(s, auth, key) {
  return (await call(s, auth, 'GET', `/rest/api/2/issue/${key}/comment?maxResults=1000`)).comments ?? [];
}

const ownComment = (c) => (c.body ?? '').startsWith(MARK);
// The crew's note goes in {noformat}, so Jira shows its ---- lines as written, not as its own markup.
const withoutMark = (body) => body.slice(MARK.length).replace(/\{noformat\}/g, '').trim();
/** A person's comment as the story's answer: its first line after "Answer:", the rest indented under it. */
const answer = (body) => `Answer: ${body.trim().split(/\r?\n/).join('\n  ')}`;

/** The story's id, as stories/AI-INSTRUCTIONS.md reads it from a file name: its first word shaped like ENG-12. */
function idOf(file) {
  return /^([A-Za-z][A-Za-z0-9]*-\d+)\b/.exec(file)?.[1]?.toUpperCase() ?? null;
}

/** The story files with a Jira key of the project, by key: where each is, and its text. */
function storyFiles(s) {
  const out = new Map();
  for (const [dir, where] of [[NEW, 'new'], [DONE, 'done']]) {
    if (!existsSync(dir)) continue;
    for (const file of readdirSync(dir).sort()) {
      const id = idOf(file);
      if (id?.startsWith(`${s.project.toUpperCase()}-`)) out.set(id, { where, path: join(dir, file), file, text: readFileSync(join(dir, file), 'utf8') });
    }
  }
  return out;
}

/** The file name for a story: its key, then its summary's words (the story's title of record). */
function fileName(key, summary) {
  const words = (summary ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 60).trim();
  return `${key}${words ? ` ${words}` : ''}.txt`;
}

/**
 * What the crew decided for a story, from its file: the last IMPLEMENTED note of a file in stories/done/
 * (moved on when it says "Not implemented: none", back to triage when a criterion waits on the BA), or the
 * last PUSHBACK of a file in stories/new/ with no answer under it yet. Nothing decided: null.
 */
function outcome(story) {
  if (story.where === 'done') {
    const at = story.text.lastIndexOf('---- IMPLEMENTED');
    if (at < 0) return null;
    const block = story.text.slice(at).trimEnd();
    const waiting = block.split(/\r?\n/).filter((l) => /^Not implemented:/.test(l) && !/^Not implemented:\s*none\b/i.test(l));
    return { block, done: waiting.length === 0 };
  }
  const at = story.text.lastIndexOf('---- PUSHBACK');
  if (at < 0) return null;
  const block = story.text.slice(at).trimEnd();
  if (/^Answer:/m.test(block)) return null;
  return { block, done: false };
}

function hash(text) {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 0x01000193) >>> 0;
  return h.toString(16).padStart(8, '0');
}

function reported() {
  return existsSync(REPORTED) ? JSON.parse(readFileSync(REPORTED, 'utf8')) : {};
}

/** check: signs in, and says what is ready and whether the two statuses a report moves cards to can be reached. Changes nothing. */
async function check(s, auth) {
  const me = await call(s, auth, 'GET', '/rest/api/2/myself');
  console.log(`Signed in to ${s.site} as ${me.displayName ?? me.name ?? me.emailAddress}.`);
  const issues = await ready(s, auth, s.max);
  console.log(`${issues.length === 0 ? 'No' : issues.length} ${issues.length === 1 ? 'story' : 'stories'} in "${s.ready}" in ${s.project}${issues.length >= s.max ? ` (the first ${s.max}: max in jira/jira.properties)` : ''}.`);
  for (const i of issues) console.log(`  ${i.key}  ${i.fields?.summary ?? ''}`);
  if (issues.length === 0) return;
  const to = (await call(s, auth, 'GET', `/rest/api/2/issue/${issues[0].key}/transitions`)).transitions ?? [];
  for (const status of [s.implemented, s.triage]) {
    const ok = to.some((t) => [t.to?.name, t.name].some((n) => n?.toLowerCase() === status.toLowerCase()));
    console.log(`  "${status}": ${ok ? `reachable from "${s.ready}"` : `not reachable from "${s.ready}" (Jira offers: ${to.map((t) => t.to?.name ?? t.name).join(', ') || 'nothing'})`}`);
  }
}

/**
 * pull: each ready story into stories/new/, written from Jira (its summary, description, the comments
 * before the crew's first, then each of the crew's comments with the people's answers under it), so a
 * story pushed back and answered comes back whole. A story already in stories/done/ gets only the
 * answers it lacks. A file whose outcome is not yet reported is left alone: report first.
 */
async function pull(s, auth) {
  const stories = storyFiles(s);
  const done = reported();
  const issues = await ready(s, auth, s.max);
  if (issues.length === 0) console.log(`No stories in "${s.ready}".`);
  for (const issue of issues) {
    const key = issue.key.toUpperCase();
    const all = await comments(s, auth, issue.key);
    const first = all.findIndex(ownComment);
    const had = stories.get(key);
    const decided = had && outcome(had);
    if (decided && done[key] !== hash(decided.block)) {
      console.log(`${key}: left as it is: its outcome is not reported yet (node jira/sync.mjs report).`);
      continue;
    }
    if (had?.where === 'done') {
      const answers = all.slice(Math.max(first, 0)).filter((c, i, list) => !ownComment(c) && list.slice(0, i).some(ownComment)).map((c) => answer(c.body)).filter((a) => !had.text.includes(a));
      if (answers.length === 0) {
        console.log(`${key}: in stories/done/, no new answer in Jira.`);
        continue;
      }
      writeFileSync(had.path, `${had.text.trimEnd()}\n${answers.join('\n')}\n`);
      console.log(`${key}: ${answers.length} answer${answers.length === 1 ? '' : 's'} added to stories/done/${had.file}.`);
      continue;
    }
    const before = (first < 0 ? all : all.slice(0, first)).filter((c) => !ownComment(c));
    const parts = [`${key} ${issue.fields?.summary ?? ''}`.trim(), '', (issue.fields?.description ?? '').trim() || '(no description in Jira)'];
    if (before.length) parts.push('', 'Comments in Jira:', ...before.map((c) => `- ${c.author?.displayName ?? 'someone'}: ${c.body.trim().split(/\r?\n/).join('\n  ')}`));
    for (const c of first < 0 ? [] : all.slice(first)) parts.push(...(ownComment(c) ? ['', withoutMark(c.body)] : [answer(c.body)]));
    mkdirSync(NEW, { recursive: true });
    if (had) rmSync(had.path);
    const name = fileName(key, issue.fields?.summary);
    writeFileSync(join(NEW, name), `${parts.join('\n')}\n`);
    console.log(`${key}: ${had ? 'written again' : 'pulled'} to stories/new/${name}.`);
  }
}

/** report: each story the crew decided, once: its note as a comment, then its card moved on (all of it done) or back to triage. */
async function report(s, auth) {
  const done = reported();
  let any = false;
  for (const [key, story] of storyFiles(s)) {
    const decided = outcome(story);
    if (!decided || done[key] === hash(decided.block)) continue;
    any = true;
    const status = decided.done ? s.implemented : s.triage;
    const to = (await call(s, auth, 'GET', `/rest/api/2/issue/${key}/transitions`)).transitions ?? [];
    const move = to.find((t) => [t.to?.name, t.name].some((n) => n?.toLowerCase() === status.toLowerCase()));
    if (!move) {
      console.log(`${key}: not reported: Jira offers no move to "${status}" from where the card is (it offers: ${to.map((t) => t.to?.name ?? t.name).join(', ') || 'nothing'}). Fix the status name in jira/jira.properties or the Jira workflow; the next report tries again.`);
      process.exitCode = 1;
      continue;
    }
    await call(s, auth, 'POST', `/rest/api/2/issue/${key}/comment`, { body: `${MARK}\n{noformat}\n${decided.block}\n{noformat}` });
    await call(s, auth, 'POST', `/rest/api/2/issue/${key}/transitions`, { transition: { id: move.id } });
    done[key] = hash(decided.block);
    writeFileSync(REPORTED, `${JSON.stringify(done, null, 2)}\n`);
    console.log(`${key}: ${decided.done ? 'implemented' : 'sent back'}; commented, and moved to "${status}".`);
  }
  if (!any) console.log('Nothing new to report.');
}

const COMMANDS = { check, pull, report };
const command = COMMANDS[process.argv[2]];
if (!command) {
  console.log('node jira/sync.mjs check | pull | report   (what each does: the top of this file)');
  process.exitCode = process.argv[2] ? 1 : 0;
} else {
  try {
    const s = settings();
    await command(s, signIn(s));
  } catch (e) {
    if (!(e instanceof Stop)) throw e;
    console.error(e.message);
    process.exitCode = e instanceof Idle ? 0 : 1;
  }
}
